//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry policy configuration.
    pub const fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn new_stores_policy_values() {
        assert_eq!(RetryConfig::new(4, 10, 100), RetryConfig {
            max_attempts: 4,
            base_delay_ms: 10,
            max_delay_ms: 100,
        });
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempt < max_attempts => {
                let multiplier = 2u64.saturating_pow(attempt - 1);
                let delay = config
                    .base_delay_ms
                    .saturating_mul(multiplier)
                    .min(config.max_delay_ms);
                sleeper.sleep_ms(delay);
            }
            Err(error) => return Err(error),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig::new(max_attempts, base_delay_ms, max_delay_ms)
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 5 { Err(RetryError::Transient("try again".into())) } else { Ok(()) }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_sleeping() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });
        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_budget_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3, 1, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still down".into()))
        });
        assert!(result.is_err());
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }

    #[test]
    fn delay_arithmetic_saturates() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(3, u64::MAX, u64::MAX), &mut sleeper, || {
            Err(RetryError::Transient("temporary".into()))
        });
        assert!(result.is_err());
        assert_eq!(sleeper.sleeps, vec![u64::MAX, u64::MAX]);
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn only_transient_errors_are_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid".into()).is_transient());
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_and_caps_delays() {
    let config = RetryConfig::new(4, 25, 40);
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        if attempts == 4 {
            Ok(())
        } else {
            Err(RetryError::Transient("service unavailable".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 4);
    assert_eq!(sleeper.sleeps, vec![25, 40, 40]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let config = RetryConfig::new(10, 1, 100);
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert!(sleeper.sleeps.is_empty());
}
